  4218 INDEX_ORDERLY_RAM_Marshal(void *array, size_t array_size,
  4219                           BYTE **buffer, INT32 *size)
  4220 {
  4221     UINT16 written;
  4222     NV_RAM_HEADER nrh, *nrhp;
  4223     UINT16 offset = 0;
  4224     UINT16 datasize;
  4225     UINT32 sourceside_size = array_size;
