  4230                                 INDEX_ORDERLY_RAM_MAGIC, 1);
  4231
  4232     /* the size of the array we are using here */
  4233     written += UINT32_Marshal(&sourceside_size, buffer, size);
  4234
  4235     while (TRUE) {
  4236         nrhp = array + offset;
  4237         /* nrhp may point to misaligned address (ubsan), so use 'nrh'; first access only 'size' */
  4238         memcpy(&nrh, nrhp, sizeof(nrh.size));
  4239
  4240         /* write the NVRAM header;
  4241            nrh->size holds the complete size including data;
  4242            nrh->size = 0 indicates the end */
  4243         written += UINT32_Marshal(&nrh.size, buffer, size);
