  4259             TPMLIB_LogTPM2Error(
  4260                 "INDEX_ORDERLY_RAM: nrh->size < sizeof(NV_RAM_HEADER): %d < %zu\n",
  4261                 (int)nrh.size, sizeof(NV_RAM_HEADER));
  4262             break;
  4263         }
